<?php
class QQWorld_Collector_Walker_Terms_Checklist_For_APP extends \Walker_Category { public $tree_type = 'category'; public $db_fields = array ('parent' => 'parent', 'id' => 'term_id'); public function start_lvl( &$output, $depth = 0, $args = array() ) { $indent = str_repeat("\t", $depth); $output .= "$indent<ul class='children'>\n"; } public function end_lvl( &$output, $depth = 0, $args = array() ) { $indent = str_repeat("\t", $depth); $output .= "$indent</ul>\n"; } public function start_el( &$output, $category, $depth = 0, $args = array(), $id = 0 ) { if ( empty( $args['taxonomy'] ) ) { $taxonomy = 'category'; } else { $taxonomy = $args['taxonomy']; } if ( $taxonomy == 'category' ) { $name = 'post_category'; } else { $name = 'tax_input[' . $taxonomy . ']'; } $args['popular_cats'] = empty( $args['popular_cats'] ) ? array() : $args['popular_cats']; $class = in_array( $category->term_id, $args['popular_cats'] ) ? ' class="popular-category"' : ''; $args['selected_cats'] = empty( $args['selected_cats'] ) ? array() : $args['selected_cats']; if ($taxonomy == 'post_format') { $slug = preg_replace('/^post\-format\-/', '', $category->slug); $output .= "<li id='{$taxonomy}-{$category->term_id}'$class>" . '<div class="custom-control custom-radio">
					<input id="in-'.$taxonomy.'-' . $category->term_id . '" name="taxonomies['.$taxonomy.'][]" type="radio" class="custom-control-input" value="' . $slug . '" ' . checked( in_array( $slug, $args['selected_cats'] ), true, false ) . ' />
					<label class="custom-control-label" for="in-'.$taxonomy.'-' . $category->term_id . '">' . esc_html( apply_filters( 'the_category', $category->name ) ) . '</label>
				</div>'; } else { $output .= "<li id='{$taxonomy}-{$category->term_id}'$class>" . '<div class="custom-control custom-checkbox">
					<input id="in-'.$taxonomy.'-' . $category->term_id . '" name="taxonomies['.$taxonomy.'][]" type="checkbox" class="custom-control-input" value="' . $category->name . '" ' . checked( in_array( $category->name, $args['selected_cats'] ), true, false ) . ' />
					<label class="custom-control-label" for="in-'.$taxonomy.'-' . $category->term_id . '">' . esc_html( apply_filters( 'the_category', $category->name ) ) . '</label>
				</div>'; } } public function end_el( &$output, $category, $depth = 0, $args = array() ) { $output .= "</li>"; } }